#define DEBUG_LOG(x)

// dumpPacketToLog - matched 83B at 0x00679560, pure dead loop once DEBUG_LOG compiles out
void NetPacket::dumpPacketToLog()
{
	Int numLines = m_packetLen / 8;
	if ((m_packetLen % 8) != 0) {
		++numLines;
	}
	for (Int dumpindex = 0; dumpindex < numLines; ++dumpindex) {
		for (Int dumpindex2 = 0; (dumpindex2 < 8) && ((dumpindex*8 + dumpindex2) < m_packetLen); ++dumpindex2) {
		}
	}
}

NetCommandList *NetPacket::getCommandList()
{
	// Frame layout matching retail:
	// commandType@esp+10, commandIDWasRead@esp+11, playerID@esp+12, relay@esp+13
	// i@esp+14, commandID@esp+18, retval@esp+1C
	Bool commandIDWasRead;
	UnsignedByte playerID;
	UnsignedByte relay;
	Int i;
	UnsignedInt frame;
	UnsignedInt commandID;

	// Explicit operator new + NULL check pattern (historical best shape 0.829)
	void *mem = operator new(sizeof(NetCommandList));
	NetCommandList *retval = (NetCommandList *)mem;
	if (retval != NULL)
	{
		retval->NetCommandList::NetCommandList();
	}

	NetCommandRef *lastCommand = NULL;
	UnsignedByte *data = m_packet;
	UnsignedByte commandType = 0;

	i = 0;
	while (i < m_packetLen)
	{
		UnsignedByte tag = data[i];
		if (tag == 'T')
		{
			UnsignedByte value;
			memcpy(&value, data + i + 1, sizeof(UnsignedByte));
			++i;
			memcpy(&commandType, &value, sizeof(UnsignedByte));
			i += sizeof(UnsignedByte);
		}
		else if (tag == 'F')
		{
			UnsignedInt value;
			memcpy(&value, data + i + 1, sizeof(UnsignedInt));
			++i;
			memcpy(&frame, &value, sizeof(UnsignedInt));
			i += sizeof(UnsignedInt);
		}
		else if (tag == 'P')
		{
			UnsignedByte value;
			memcpy(&value, data + i + 1, sizeof(UnsignedByte));
			++i;
			memcpy(&playerID, &value, sizeof(UnsignedByte));
			i += sizeof(UnsignedByte);
		}
		else if (tag == 'R')
		{
			UnsignedByte value;
			memcpy(&value, data + i + 1, sizeof(UnsignedByte));
			++i;
			memcpy(&relay, &value, sizeof(UnsignedByte));
			i += sizeof(UnsignedByte);
		}
		else if (tag == 'C')
		{
			UnsignedShort value;
			memcpy(&value, data + i + 1, sizeof(UnsignedShort));
			++i;
			memcpy(&commandID, &value, sizeof(UnsignedShort));
			i += sizeof(UnsignedShort);
			commandIDWasRead = TRUE;
		}
		else if (tag == 'D')
		{
			++i;
			NetCommandMsg *msg = NULL;

			switch ((NetCommandType)commandType)
			{
			case NETCOMMANDTYPE_GAMECOMMAND:
				msg = readGameMessage(data, i);
				break;
			case NETCOMMANDTYPE_ACKBOTH:
				msg = readAckBothMessage(data, i);
				break;
			case NETCOMMANDTYPE_ACKSTAGE1:
				msg = readAckStage1Message(data, i);
				break;
			case NETCOMMANDTYPE_ACKSTAGE2:
				msg = readAckStage2Message(data, i);
				break;
			case NETCOMMANDTYPE_FRAMEINFO:
				msg = readFrameMessage(data, i);
				break;
			case NETCOMMANDTYPE_ROUTERFALLBACK:
				msg = readRouterFallbackMessage(data, i);
				break;
			case NETCOMMANDTYPE_PLAYERLEAVE:
				msg = readPlayerLeaveMessage(data, i);
				break;
			case NETCOMMANDTYPE_DESTROYPLAYER:
				msg = readDestroyPlayerMessage(data, i);
				break;
			case NETCOMMANDTYPE_KEEPALIVE:
				msg = readKeepAliveMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTKEEPALIVE:
				msg = readDisconnectKeepAliveMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTPLAYER:
				msg = readDisconnectPlayerMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTCHAT:
				msg = readDisconnectChatMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTVOTE:
				msg = readDisconnectVoteMessage(data, i);
				break;
			case NETCOMMANDTYPE_CHAT:
				msg = readChatMessage(data, i);
				break;
			case NETCOMMANDTYPE_PROGRESS:
				msg = readProgressMessage(data, i);
				break;
			case NETCOMMANDTYPE_LOADCOMPLETE:
				msg = readLoadCompleteMessage(data, i);
				break;
			case NETCOMMANDTYPE_TIMEOUTSTART:
				msg = readTimeOutGameStartMessage(data, i);
				break;
			case NETCOMMANDTYPE_WRAPPER:
				msg = readWrapperMessage(data, i);
				break;
			case NETCOMMANDTYPE_FILE:
				msg = readFileMessage(data, i);
				break;
			case NETCOMMANDTYPE_FILEANNOUNCE:
				msg = readFileAnnounceMessage(data, i);
				break;
			case NETCOMMANDTYPE_FILEPROGRESS:
				msg = readFileProgressMessage(data, i);
				break;
			case NETCOMMANDTYPE_INFORMPLAYERLEAVEFRAME:
				msg = readInformPlayerLeaveFrameMessage(data, i);
				break;
			case NETCOMMANDTYPE_REQUESTPLAYERLEAVE:
				msg = readRequestPlayerLeaveMessage(data, i);
				break;
			case NETCOMMANDTYPE_REQUESTFRAMEDATA:
				msg = readRequestFrameDataMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTFRAME:
				msg = readDisconnectFrameMessage(data, i);
				break;
			case NETCOMMANDTYPE_DISCONNECTSCREENOFF:
				msg = readDisconnectScreenOffMessage(data, i);
				break;
			case NETCOMMANDTYPE_REQUEST_GAMESPY_STATS_AUTHKEY:
				msg = readRequestGameSpyStatsAuthKeyMessage(data, i);
				break;
			case NETCOMMANDTYPE_GAMESPY_STATS_AUTHKEY:
				msg = readGameSpyStatsAuthKeyMessage(data, i);
				break;
			}

			if (!msg)
				break;

			msg->setExecutionFrame(frame);
			msg->setPlayerID(playerID);
			msg->setNetCommandType((NetCommandType)commandType);

			if (DoesCommandRequireACommandID((NetCommandType)commandType))
			{
				if (!commandIDWasRead)
					++commandID;
				msg->setID((UnsignedShort)commandID);
			}

			commandIDWasRead = FALSE;

			NetCommandRef *ref = retval->addMessage(msg);
			if (ref)
				ref->setRelay(relay);

			if (lastCommand)
			{
				delete lastCommand;
				lastCommand = NULL;
			}
			lastCommand = new NetCommandRef(msg);

			msg->detach();
		}
		else if (tag == 'Z')
		{
			++i;
			if (!lastCommand)
				break;

			NetCommandMsg *msg = NULL;
			unsigned originalExecutionFrame;

			if (commandType == NETCOMMANDTYPE_ACKSTAGE1)
			{
				msg = new NetAckStage1CommandMsg;
				NetAckStage1CommandMsg *last = (NetAckStage1CommandMsg *)lastCommand->getCommand();
				((NetAckStage1CommandMsg *)msg)->setCommandID(last->getCommandID() + 1);
				((NetAckStage1CommandMsg *)msg)->setOriginalPlayerID(last->getOriginalPlayerID());
				originalExecutionFrame = last->m_originalExecutionFrame;
			}
			else if (commandType == NETCOMMANDTYPE_ACKSTAGE2)
			{
				msg = new NetAckStage2CommandMsg;
				NetAckStage2CommandMsg *last = (NetAckStage2CommandMsg *)lastCommand->getCommand();
				((NetAckStage2CommandMsg *)msg)->setCommandID(last->getCommandID() + 1);
				((NetAckStage2CommandMsg *)msg)->setOriginalPlayerID(last->getOriginalPlayerID());
				originalExecutionFrame = last->m_originalExecutionFrame;
			}
			else if (commandType == NETCOMMANDTYPE_ACKBOTH)
			{
				msg = new NetAckBothCommandMsg;
				NetAckBothCommandMsg *last = (NetAckBothCommandMsg *)lastCommand->getCommand();
				((NetAckBothCommandMsg *)msg)->setCommandID(last->getCommandID() + 1);
				((NetAckBothCommandMsg *)msg)->setOriginalPlayerID(last->getOriginalPlayerID());
				originalExecutionFrame = last->m_originalExecutionFrame;
			}
			else
				break;

			((NetAckBothCommandMsg *)msg)->m_originalExecutionFrame = originalExecutionFrame;
			msg->setExecutionFrame(frame);
			msg->setPlayerID(playerID);
			msg->setNetCommandType((NetCommandType)commandType);

			if (DoesCommandRequireACommandID((NetCommandType)commandType))
			{
				if (!commandIDWasRead)
					++commandID;
				msg->setID((UnsignedShort)commandID);
			}

			commandIDWasRead = FALSE;

			NetCommandRef *ref = retval->addMessage(msg);
			if (ref)
				ref->setRelay(relay);

			delete lastCommand;
			lastCommand = NULL;
			lastCommand = new NetCommandRef(msg);

			msg->detach();
		}
		else
		{
			dumpPacketToLog();
			++i;
		}
	}

	if (lastCommand)
	{
		delete lastCommand;
		lastCommand = NULL;
	}

	return retval;
}
